  VALUES 
    (114::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-11-03T00:00:00+00:00'::TIMESTAMPTZ, '3eec192d4ebf88b42e1d505bd50acf671f8d974cca928d69fcde3d60f213f340'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Usted no pierde el curso pero ni queriendo,puede hacer los informes con ia que si lo pone en las referencias se lo pasa,fue un curso que pasé con 95 un semestre en donde perdí 3 materias,imaginense jajaja, volvería a matricular con el lo que sea'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2026-07-24T00:00:00+00:00'::TIMESTAMPTZ, '8d6c5dd3d637b8df8a2c6675e478940fdb64edd5e398ffe77af2f4d6fe6bbc92'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Ud va a matricular presencial y él lo va a cambiar a asincrónico. Cuando ud ve aquí q va a tener q leer mucho, creaselo, pq hay que hacer una infinidad de informes de lectura (una lectura era de más de 100pgs). Mejor ni le mande correos pq no contesta. Las instrucciones son la definición de confuso.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2026-07-05T00:00:00+00:00'::TIMESTAMPTZ, '50ca9b2babf660684faead76dfa9cb6475ef78bd680baaca49a0de8024943b06'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Para este curso es un profe muy chill. El curso era presencial pero solo fuimos una vez y el resto asincrónico. Revisa todo al final del curso, yo creo que toda la clase sacó 100, deja trabajo todas las semanas, un poco largos pero nada del otro mundo, si se la quiere tirar rico es con Bojorge.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, '683769e9c46d2db944dfc5256194a3f52cacb772e870379d974bd8ea846a27d4'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Es simplemente increíble, fue una clase que disfruté demasiado, el profe es increíble, se interesa en los estudiantes y busca que la actualidad y los conceptos de la clase se relacionen. No es una clase que realmente uno es ajeno con todo, como pasa con otras personas. Definitivamente un profe cool'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2025-10-02T00:00:00+00:00'::TIMESTAMPTZ, 'ec221e6c877409406b58fca4e11fa4758b209d9be17cfde532b9b41f4eae8cf5'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'La clase se basa en lo que el opine del tema que se habla, solo importa los trabajos grupales normalmente es uno por semana y en ese aspecto es importante tener buenos compas de grupo porque si no le va a costar más pero con que entregue todo tiene 100, los exámenes son trabajos cortos básicamente'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e0ed8114185b5e77d6fa8c5e88ce69d4d3c644aa980c7adc44a8d5a6d27501e4'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Deja lecturas semanales muy largas, informes grupales eternos, y entregas con muy poco tiempo. No responde correos, no está en la oficina ni contesta por Telegram. Se la pasa desmotivando a los estudiantes, diciendo que el TEC es muy difícil. Narcisista, egocéntrico, ignorante, innecesariamente hard'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a16e70ce2eeeb2d5ac5dd2d9c3bb0dd9358e18790b96ebfff26bb974de59c9e1'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Con todo el respeto del mundo, que mierda de profesor, ni él sabe que está calificando, pasa todo el semestre y no hay un medio fijo donde atender dudas o saber cómo van las calificaciones, la mitad del semestre se ausenta y las clases son todavía más aburridas que escucharlo hablar -10000000/10.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'd19ed6c0bd5c7f12dd8e780997e95818cd2d40ed16236f2158e9820c150f5e57'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Nunca responde correos ni el telegram, deja informes de lectura enormes todas las semanas. No tiene empatía y juega de muy ético.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '6eaf9a97412a88c6cd9f9d1d2c0e9504d23a82f5efd3257e19fbcecab4635129'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'que se retire para que mejore el curso, no ayuda, envía lecturas interminables, califica muy duro, no contesta el correo ni telegram'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2025-06-10T00:00:00+00:00'::TIMESTAMPTZ, '8b67603c608f412a6998e440b421b59b49ef42b7db5ab5a2d4bd90771cceb98b'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2025-05-09T00:00:00+00:00'::TIMESTAMPTZ, 'd7a26042fefea8978fdc4b4fdaee47e4e0e0a4ce0a76d17a41b9448d07f9090e'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'No lo matriculen, es un mal profesor, no tiene interés en la clase más que hablar mal del gobierno y de USA, un socialisto de toda la vida. Deja lecturas muy largas todas las semanas, informes grupales eternos, no responde correos, no responde el telegram, no está en la oficina para hacer preguntas.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2025-04-26T00:00:00+00:00'::TIMESTAMPTZ, '5bcd31b9ae2ac944073e695311e1506924dc13c8671fbe4f4eefa03d35267a95'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Prepotente, juega de vivo, califica con los pies, se pasa fácil porque al final él pone la nota que se le pega la gana, matriculen con él si no hay de otra'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-08T00:00:00+00:00'::TIMESTAMPTZ, '0d7de7f71ab286bf1a2f515cc49c00d48ba49a7a5ed2458a1acf5c7a35573d1c'::TEXT, ARRAY[980, 981]::BIGINT[]),
    (114::BIGINT, 'El mae piensa y juega de vivo de que el es la persona más etica del mundo, tenia que subir la clase los lunes, y la subia cuando le daba la gana, no contesta correos y nunca esta en la oficina, además deja trabajos extensos y no explica bien lo que hay que hacer, si le cae bien pasa, si no no'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-11-19T00:00:00+00:00'::TIMESTAMPTZ, '3678fe574ec228c3d04867794f5a51c6d3563fe8b0f6a044f3572d5f2efd790e'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'En sus clases en linea no da información, no explica el tema y siempre da horas de oficina cuando el no se encuentra. No contesta correos, el siempre esta en lo correcto y uno no tiene opinión'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-05-14T00:00:00+00:00'::TIMESTAMPTZ, 'f7fb3e8ad3224fcaebe47d80544f30d659327054c5879e80c730dca7f9d3088b'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Que asco de profesor, quedo a todo el curso solo por que "le caiamos mal"'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '129d6674d179eb3627b6631f109460c53c6198b31f43dcf6dff5b629a38b4597'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'No entiendo como tiene tan mala calificación, el profesor es bastante bueno, la clase es entretenida, trata temas picantes que a mas de uno le enchila eso si. Con que entregue los trabajos que asigne es mas que suficiente para pasar el curso. Si quiere retroalimentación debe de ir a consulta.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'e93f5d02af5e6d275b43a4c4414d010ea2f91bde81785853d9d6729e09a26485'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Informes de lectura cada semana, pero este semestre todo fue en grupo entonces fue mas facil, trabajo de investigación y una exposición grabada, cero feedback de los trabajos eso sí. Asistencia obligatoria. Nada mas vaya a clases y no falte con ningun trabajo y el mae te pone un 100 al final.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2023-11-16T00:00:00+00:00'::TIMESTAMPTZ, '414049fb4f1b224b590e3f48e39ffe67a05703f186730dce310c9322e0837177'::TEXT, ARRAY[980, 981]::BIGINT[]),
    (114::BIGINT, 'Es un profesor que no da retroalimentación, pero si usted hace todos los informes y trabajos, tengalo por seguro que va a pasar, realmente no entiendo porque tiene tan mala calificación.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '8f8b13ade14bb3bf2b727147d2695c76e56c08d9f84d907716828013c44cb128'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Clases bastantes chill, se realizan informes de lectura todas las semanas o la mayoría de estas. Como 3 trabajos grupales de investigación con exposición incluida. No da retroalimentación y tampoco sube notas. Si entrega todo y va a todas las clases pasa con 100.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, '6975f512386186a685863af0c12d914b0de0ba3ef1bf11ec1e12646d02f4f3c4'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'La verdad que el curso no sirve de nada en la carrera entonces para mi no me importa si da bien o mal el curso a todos nos puso 100 y eso es lo que importa. Muy llevadero.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, '1e3493010facd28e899e42a6c32420531038c323e6c50fd21bc93b368b6c1f49'::TEXT, ARRAY[981]::BIGINT[]),
    (114::BIGINT, 'Pésimo profesor, todas las semanas un trabajo nuevo, da 0 retroalimentación o instrucciones. Nunca envío la calificación de ningún trabajo , si contesta un correo es cuando le da la gana y no responde claro. Todo esto para que en semana 18 diga que ya subió las notas a registro, sin ningún aviso.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'ff2ee5d14781c375baccbb103715f3d667a2bf408ab8eb76e25344584a00b04e'::TEXT, ARRAY[981]::BIGINT[]),
    (114::BIGINT, 'Básicamente, llevar la clase con el es demasiado matado, aburrido y su narcisismo es fatal, ya que, solo el tiene la razón y solo su opinión importa, no da retroalimentación, informes de lectura extremamente largos, que ni siquiera revisa, no lo recomiendo. EVITEN A TODA COSTA MATRICULAR CON EL.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '8c471dea2988ab097e98060fa266b08a9edc181c39f9c4ad86914c258c05a488'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-24T00:00:00+00:00'::TIMESTAMPTZ, 'aa162bb2221c5eefb172b5cb9ab44bb83c5589928507c341f4ed41feb9e3cb5a'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Pésimo evítenlo todo lo que puedan. Pide informes de lectura cada semana, para al final calificar con un copy paste a todos los estudiantes. Cuando pasa diciendo que el lee cada uno de los informe. pura mierd'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-05-18T00:00:00+00:00'::TIMESTAMPTZ, '11faf3dee8e97d0f4e779c5e2c8c02bec22c0ddeaafc16c178bc3f67b9460309'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Pésimo profesor. Se cree lo mejor de este mundo y las clases son 90% el quejándose de que no hacemos las cosas bien y el profesor ni siquiera revisa los trabajos, literal le pone la misma nota, comentarios y errores a TODOS y manda los trabajos juntos a todos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2022-04-02T00:00:00+00:00'::TIMESTAMPTZ, '8ad65660e3ae591342e048d20a7fba620162b1cf2792ea4c962e875e56128315'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Se cree super pichudo y etico, si pueden mejor matriculen con otro profesor. Es un dolor de picha.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2022-03-16T00:00:00+00:00'::TIMESTAMPTZ, '9d88a12b9120beedb23d6b5d58c32a8a0c5b0d821077a00ddfd25b6dc7fa9305'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Un completo hijueputa'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-20T00:00:00+00:00'::TIMESTAMPTZ, '530d70254a9c2302023ebaed9515cec8543ada0416f3646f26ebff7db993aaa6'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Resumido: viejo carepicha'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, '1fd98c4de3bb8dbfb4da72fa59b700ba09355a899d4755cd1fd8dd16905e4f51'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'El profe cae mal, es súper pedante y se cree la última chupada del mango. Las clases son inútiles. Deja demasiados informes y nunca explica cómo los quiere ni da guías ni nada y se queja que están mal hechos. Al final califica como le ronque el c*lo y pasa a todos con buena nota.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '8fb7e064c99ba41f309d4857fa602bca345deb021bd6e15842573f1f62f3c7ec'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Un chiste de profesor. Deja una cantidad increible de informes de lecturas larguisimos que nunca va a revisar y un trabajo final con instrucciones super ambiguas. Su nota solo aparece magicamente al final de semestre si entrego todo. Todo esto sin mencionar la actitud pedante del mae.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-11-01T00:00:00+00:00'::TIMESTAMPTZ, 'bc2bc45b89c6ed9e4913dd38b93b5c261bf24996f4c5dc2fb1be569b8a865f11'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Pésimo, poco ético e irrespetuoso. No ayuda en nada y deja montones de tareas que revisa generales y muchas ni las revisa. Es de los profesores que quieres evitar durante la carrera.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '57cfc1b8efabff1255e266cfed631d864e65215909018bd01d21506b9a3d3b0a'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Ni bien, ni mal'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'f1ba96839cfeea22877137478d9e71af91fb5cd4e836fabef435f8933c258be4'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Pésimo profesor de lo peor que tiene el TEC, clases aburridas y largas, habla mucha paja, deja muchos informes y no explica como hacerlos de la forma que el quiero, si tu grupo o tu no le agradas ten por seguro que no pasas, califica hasta el final del semestre, NO MATRICULEN CON EL.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '51d40aa0ef175c99a6fec1dd8efd285d5c774e18db08cbe5d45eef8a8c0da781'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'El mae solo comentarios negativos y nada de retroalimentación. Pésimo profesor. No da calificaciones hasta el final. Nada más le gusta dar mala vida a los estudiantes. NO MATRICULEN CON ÉL.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c9d44331c21af7019c99cead9f4ec331b130b1708225f313d5fcea3623e832a4'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'JAMÁS matriculen con él, no contesta correos nunca, no devuelve los trabajos calificados solo dice comentarios negativos sobre los estudiantes sin comunicar que hay de malo en los informes.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'a03c27b0d891cd86962f5502dae152011c0a6ecff4bdd1fdc26de281ad21e66e'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Nunca, pero NUNCA matriculen con este mae, deja informes muy largos, nos ha puesto cero en todo, y para las últimas semanas dejaba documéntales de más de 40 minutos e incluso dos informes por semana, todo por un crédito, si se quiere hacer la vida cuadritos matricule con este mae.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'fff402328ad503bf68529adf198e5ba341bf6c5f484eb7c98472ae5cc8f8ce94'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'el grandísimo hp le puso 0 a todos solo porque se le hincharon los huevos no lee lo que los estudiantes le envían califica en general los trabajos no individual'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-03-11T00:00:00+00:00'::TIMESTAMPTZ, 'c83fed25482855e4e1f074511f596c4043ec5bef152c8a6ee7ea8de624d16f8b'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, 'de2ca28bf43fa51f757590c470ff704a4166108880f924f5caab638bc4797f77'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Pésimo, deja demasiados informes y nunca los revisa. Al final gastas tiempo leyendo y haciéndolos para que se los dé por calificados a todos, no valora ese esfuerzo. Y los exámenes son súper ratos. Es fácil pero hay mucho mejores opciones.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'ead01c9662a56dc1425b0c13fa8ed39e73a07b3467ba55fa3d9923288682f0e6'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'En todo el semestre encargó muchos informes de lectura del que nunca dio calificación de ninguno, poniendo excusas de por qué nunca entregaba notas. Nunca contesta correos y el segundo examen fue muy largo para el tiempo que tiene uno para hacerlo, no metan con él, jamás nunca.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2021-01-30T00:00:00+00:00'::TIMESTAMPTZ, '2457a9859289228d32769ccfe40e17c40e7a4a8a0cf90b636d61c0fe6e22e508'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Este mae es una mie@#~€. Nunca contesta los correos, se contradice constantemente y el curso le vale pi@#~€ porque al final le puso 100 a todos.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, '58369505ae26fb1b113bb5d2523c800fd87464228100b96e6db4f46f16987cc6'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Pues tienen que ponerle atención a todo lo que dice, pues deja muchos informes de lectura y uno tiene que estar al tanto de lo que pide, en muchas ocasiones lo dice todo disimulado. El profe no califica rudo, pero uno tiene que poner de su parte.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'fb998d2bf504b144022890fabf30c4ea8d418eb3810913ecc482a01100310077'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-10-12T00:00:00+00:00'::TIMESTAMPTZ, 'f7baea893507e1783ef635db399e760e4825b4c899b4fdb7ab95d84c7ae4a610'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Clases virtuales: desastre. Si no da cronograma (pídaselo). No tiene empatía con los estudiantes. Después de una queja con la directora, de un grupo de estudiantes y al final puso un examen que casi nadie pudo terminar. Al final nos dio 90 o 100 a la mayoría sin un por qué.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, '3e57d442a4ccb56dadf5b4880fa24e0f64cbfab52dd1023e8fc944592085c392'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Es un profesor que califica por grupo. Si el grupo le cae bien, le va bien. Siempre deja lecturas que son largas, y aveces en clase se desvia del tema. Es muy indiferente con los estudiantes. Le recomiendo que sus informes sean de la maxima extension, eso ayuda con la calificacion.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, 'b0b96f09bcf78373da1dc6f9adac98312faff0ab429fe8fd4bc555a8c15f0803'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'los examenes son muy dificiles. ademas que las lecturas son muy extensas de vez en cuando. al final del curso el profe tiene compasion.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'e5269d8ec0164f625c924020de6ee284e69bf860cf6bfbc21c96a19a3683bc9b'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Demasiado irresponsable, con las lecciones virtuales era un desorden y en el TECDigital, no entrego ningun informe revisado, el segundo examen tampoco lo entrego revisado, pedia respeto y nos los faltaba con todo esto, dejo mucho que desear'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '21035462b81e464e74667d933b1965183eb38eb0b33d72cdfd196d43b4455756'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '5d84ff2f8a55c10c45108047bc99c023b1d584f79c33f89ed3d8d270b1b71fbc'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Es un profesor super irresponsable en el grupo en el que estaba no regresó los informes de lectura que pedía cada semana, las clases la verdad son un poco confusas y siempre deja mucha lectura para una semana.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '6432e1f9e2e0ee384c477f335b7a94a58187c8a543db61a0db67cf23cb36a5e5'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Es buen profe pero para una materia como intro es muy exigente, pide leer biblias de texto y como que no para una materia de un crédito. Igual es man es amable pero hay que ponerle, cada semana deja un reporte de una lectura y que bostezo'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'df576c3e985ea34beb9f7d4e13a03dc06f3738e5d37678aedd97c67041e3d213'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'No lo recomiendo. No responde mensajes ni correos, califica a como él quiere, muy desorganizado e impuntual.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, '59538de930c7cc8370ea30bef2af30b37aab25dcccd235048a544c0823daca11'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'un profesor muy vago , no lo recomiendo para nada'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'bd5fb55cad20a6702f5b3b7524de6b57d1eea2460e83f02ad66006a185aabc1a'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'No matricule con el. sus clases son aburridas, los examenes pesados y no sabe ni como los califica. Nunca responde mensajes. Con la modalidad virtual no le importa las dificultades de los estudiantes. Para cumplir con las metas simplemente pone un par de documentales y lecturas largas. Mal profe'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-08-01T00:00:00+00:00'::TIMESTAMPTZ, 'c6328d75d212a82ab9cb44d972bc7d221f6740df50b681d98a938ed14015622d'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-15T00:00:00+00:00'::TIMESTAMPTZ, '9719d40081ccaa61e5599a6a390d1648d369678879e2c030db6403b98aafcc85'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'La mala metodología empleada, el desdén con el que se dirige hacia los estudiantes, los alardes de grandeza que se da, la ignorancia respecto a muchos temas de los que se cree conocedor y muchos otros aspectos que no incluyo por la limitación de caracteres, dan mucho que desear de su "maestría".'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2020-07-02T00:00:00+00:00'::TIMESTAMPTZ, '28ca0f1fea31cc70bb0c2a5c733794a662d98043e4f48edd71698026953ec619'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Parece que el curso es de 4 creditos:/'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-29T00:00:00+00:00'::TIMESTAMPTZ, '42c14e3e4f193f7f0110528d49034d3138c61fdf92980b87c21fc1ade398f662'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Califica como le da la gana. Con las clases virtuales ha sido terrible, no toma en cuenta los problemas de los demás y luego en clase dice que está al servicio de todos cuando es mentira. No toma en cuenta la opinión de los demás. Las clases son aburridas. No matriculen con él.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2020-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'b28761f8286c3511001df453b2e41946e8087bdd573eb3d500cd0d0a8752109e'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Excelente, recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2020-01-16T00:00:00+00:00'::TIMESTAMPTZ, '5ad443cd78c31ea175e497b0d8ab2fec7388033a555c981e94a2125dac5cefe8'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Muy buen profe, motiva en sus lecciones. No hagan caso a los malos comentarios que hay de él. Lo único malo es que da notas hasta el final.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Clases excelentes']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '398e764dd31a25d13bc47b8584a7af7a5727e5ccfb6a12632f5ead62a425472b'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'el mae es un desmadre, uno no sabe como le va porque los reportes que deja los entrega hasta el final'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-28T00:00:00+00:00'::TIMESTAMPTZ, '59da57091c1c9abb174eb78453a834c5d8a37837f46e0ac06b3f08afa5de45a5'::TEXT, ARRAY[980, 981]::BIGINT[]),
    (114::BIGINT, 'Las clases no son aburridas, el mae cae bien. Pero deja informes de lectura para todas las semanas, quita demasiado tiempo para un curso tan poco importante y de un crédito. Los exámenes son duros, y califica como le da la gana. Dependiendo de si le cae bien o mal el grupo. Para nada recomendado.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '72d0dab544f472e353ae5678e52ddc28a58ac4743bdb69ca4a095e5ba7873cbc'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Este curso es en teoria facil, este profesor se toma muy en serio el curso, deja informes de lectura todas las semanas por lo que hay que dedicarle bastante tiempo al curso, pone notas muy en general'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '2ff67de9aebc1bf976166e0a73bafa1f2231729d8a6ed9d3f1193abc4f70c224'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Califica demasiado duro en los exámenes y reportes; sin embargo, las clases no son aburridas'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2019-06-09T00:00:00+00:00'::TIMESTAMPTZ, '1cd028af0c941a55c701f8020c89bb60841e2c3545c2605e5634233ee8bb0546'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Lo único que hace es jactarse de lo "bueno" que es, menosprecia a los estudiantes dependiendo de qué tipo de educación(pública, privada, científico, etc) obtuvieron, generaliza las notas de los trabajos o exámenes, pretende que los estudiantes pongan atención, pero habla pendejas irrelevantes.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2019-06-02T00:00:00+00:00'::TIMESTAMPTZ, '98a7f31efcc3075d27c09f1a5d3dbe40a28e0df3564a8e450550a187244c9625'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Nunca matriculen con él, es una materia super fácil pero él la hace un mundo... Matriculen com otros profes Esta materia no debería de quitarte tiempo del todo Aparte él es pésimo o sea nunca matriculen nada con él'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2019-05-31T00:00:00+00:00'::TIMESTAMPTZ, '000efd3ffb612821e0c47956b82d5e600cd5730c70b8065f363f5e9131ee8a8e'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Las clases constan de tiempo para leer los documentos en el digital, los examenes son de fragmentos especificos de las lecturas y generalmente califica suave si uno sabe de lo que esta escribiendo, hay que hacer resumenes de cada lectura pero si se hacen con apa se pueden hacer de cualquier cosa'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2019-05-28T00:00:00+00:00'::TIMESTAMPTZ, '7c2a5df827506077bd5e4655cbc03cbf82e39dd1d20edcc616b1865cbbd22090'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Pésimo profesor. No se digna a leer los exámenes ni trabajos y pone notas a cómo le plazca, esto dependiendo si el grupo le agrada o no. Pide ciertas cosas en los trabajos y a la hora de calificar cambia la versión para bajar la calificación.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-08T00:00:00+00:00'::TIMESTAMPTZ, 'd83bf7d80011a53062de9a53b87c95f705ed317371b5a60a828c9b9130fb6989'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Buen profe, en realidad no pide mas que resúmenes de lecturas y vídeos que se ven en clase, nada del otro mundo, ya que son lecturas fáciles. La monografia final es super sencilla. No va dando las notas de los resúmenes, ni tareas, todo lo da hasta el final, pero no es muy exigente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'cf61c602c47531c3852b1749169832eefea205eed21181c7cb7a84694095b2c7'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Al final del semestre el profesor califica basándose en el grupo que tuvo y no en el esfuerzo que puso cada estudiante en los trabajos, no tiene el desglose de notas y le gusta cuestionar la opinión de los estudiantes pero de una manera poco profesional.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-01-10T00:00:00+00:00'::TIMESTAMPTZ, '2c0cb815bcadeeda7c55346ce3e1a8d05ac5da108651677f6a693079d960908f'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'De los peores profes del Tec'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2018-12-12T00:00:00+00:00'::TIMESTAMPTZ, '538dcf764c4c226da5df0bdf9d8ac0fd4e45762fcab9d9e27414e27902be1d90'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'El profe solo habla en las clases por lo que se hacen muy largas y aburridas, además da a entender que solo lo que él piensa está bien. Deja muchos trabajos y no los revisa, al final pone la nota a su antojo.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '12d0f1f036193c0568803687f6dd645623ad644087ea648f8e7c5ed190397ae6'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Las clases son solo escucharlo hablar paja. Deja informes todas las semanas y ni siquiera los revisa, solo pone checks. Es aburrido y a veces lo que hace es poner documentales que ni se escuchan bien. Si puede, mejor no matricule con el.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, '57eb1aaccf9996cc7b3d30f36637c1866bd89de53b95925c1132b4f9f907a81a'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes']::TEXT[], '2018-11-04T00:00:00+00:00'::TIMESTAMPTZ, '6cc9f3e228a205a54e9a424386b54b1fd26e35ff5f86c844b1d2510c3e675a69'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Excelente profe, deja lecturas pero son cortas (importantísimo leerlas), el curso lo hace muuuuy interesante y no aburre... Se le entiende todo, se interesa por el aprendizaje.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'd1ac1253e8b21747a49927db04c9bcefa34a9937871029be4011edc4d851a9f9'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Muy buen profesor, hace las clases super interesantes. Deja tareas que son hacer un resumen de una hoja de alguna lectura y al final una monografía de 12 páginas. No puede faltar a ninguna clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, '9c4b0400bd4e672ec94ae7a63bdb6f511f78c0d54c6290cc683010ae8feb9db3'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Buen profe, las clases son interesantes, no demanda mucho tiempo el curso porque deja tareas sumamente sencillas y el proyecto también. Lo único es que nunca se sabe nada respecto a las notas de las evaluaciones, sino hasta el final del curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'a82e38973201c256a1715fc2d1922941fec7f3c0493c6134a104a641763f2c86'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Un profe que hace las clases sumamente interesantes con dilemas éticos reales. Hace el curso muy sencillo de aprobar. Tareas fáciles y proyecto muy sencillo. No se atreva a faltar a la clase y la participación es importante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '614841acacb3c671415f01b0ed7d9b20824d56e2ba29466c935995d6bbff41f9'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Excelente profesor. Las clases son muy interesantes y entretenidas. Se interesa por el aprendizaje del estudiante y no demanda mucho tiempo, super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, '9fa658168b0f209d19611e27d1aed71ea9fd1ba66662ca5baf7aca24e9ded94d'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Demasiado buen profe, las clases son muy interesantes y con él el curso no demanda mucho tiempo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'd20c957ec9e0c180fa2a476ad73c558b67a25d4c7507f0fb4cd5dfcda2cf1674'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Deja lecturas en el el Tec-Digital para llevar un resumen de una página, al final sólo se hace un trabajo de 12 pág.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros']::TEXT[], '2018-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'c1eff86f4aa090d6627d34fb07fb49ad73e17c9d39c7bd766687b6e0b90372ac'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Las clases son ir a escuchar y participar, pero se pasa fácilmente el curso. Sí es un poco estricto con el examen de cátedra.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '7f55b6a03b69558902d00816453e423dd2ca6d08bd92cd0ea1a4ec62563d9c6c'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Sólo puede faltar una vez, deja unas lecturas en el tec digital y tiene que hacer resúmenes de una página, pero las clases son demasiado entretenidas! Al final hay que hacer una monografía de 12 páginas y está listo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '9dfae37f0159ae714e5cde325f1e8a3c57a49b7cb47b81612ed438c1b25b0a8e'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2017-07-13T00:00:00+00:00'::TIMESTAMPTZ, '52045672bd7084efd020e923ce0b2dd6287be37dbde11526e9338726002b54f8'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Hace las clases muy interesantes y dinámicas. Se preocupa porque a sus estudiantes les guste la clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '91a7bb0664bf9c86a55dcc59afecbbe2a5b8cc419c08ab030fb952f770754536'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Deja muchos trabajos, pero son bastante sencillos y califica muy suave. Además, hace la clase muy interesante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases excelentes']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, '6a647a0e160d26a835ee23888b4c7e59b33f438cae8b19cb5d60d2b0acc82d2f'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Es un excelente profesor, aborda muy bien los contenidos, realiza la clase sumamente interesante e inspiradora. La calificación de los trabajos es suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-06T00:00:00+00:00'::TIMESTAMPTZ, '9b1d9c6f6a85b9a3ee768e092070c576cee0332c35e0e19fb8eb7d6912b0f29a'::TEXT, ARRAY[559]::BIGINT[]),
    (114::BIGINT, 'Excelente profesor, es muy buena gente, se nota su interés tanto por enseñar como por ayudar. El mejor y se pasa muy facil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'b7e9911b88ccf6ec62d6c7c468dec15b3e01f7d81a48f78fcdc02c64f915a0c8'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'eb81d3a6d38beea900fdf880fa2a96c566b936a18c5208c08f00d6a9e3680158'::TEXT, ARRAY[980, 981]::BIGINT[]),
    (114::BIGINT, 'Hace las clases no tan aburridas y se pasa muy facil sin hacer mucho. Es muy buena gente, lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '60d4907ff67b14b4c0abfeff80132abe9062b95e23fa3733128a0d71022195e2'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Muy buen profe. Deja lecturas y tareas pero nada extraordinario. Las clases son interesantes. Excelente profe y persona, muy recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'e5705d6afc0afe73e7551945a72c2c411267dc35132f8f165610a527fa9fe05b'::TEXT, ARRAY[981]::BIGINT[]),
    (114::BIGINT, 'Profesor Excelente, dedicado y muy profesional, atento y quiere que los estudiantes aprendan mucho. Super recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-10-28T00:00:00+00:00'::TIMESTAMPTZ, 'ac791664956104d8092bda18128bc10ab3d056f60fd33a719c2387301ab54174'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Excelente persona y profe! Es nuevo, es super profesional y su interés por que los estudiantes aprendan es muchísimo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'dc034c1fb4b676f138fa77242eccad3b6bdcc058fed92fd981ee13bab39d7270'::TEXT, ARRAY[980, 981]::BIGINT[]),
    (114::BIGINT, 'Profe excelente. Muy atento, muy inteligente, y su interés de que los estudiantes aprendan y sean excelentes profesionales lo hace admirable. Recomendado 100%.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e4df8fe02ac0d7defd47c5808293d592f0919debe46d737899ee629c9c9c8e19'::TEXT, ARRAY[980]::BIGINT[]),
    (114::BIGINT, 'Es nuevo y hace que el curso sea relax'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-17T00:00:00+00:00'::TIMESTAMPTZ, '13385e361af13b52c5f3ea408298bcb547429ccce7803bddbc4ffddd22d9809c'::TEXT, ARRAY[980, 981]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
